import type React from "react";
import { C } from "../theme";

// Geometry copied from media/brand/mark-brass.svg (generated by media/brand/build.mjs).
// Split into parts so the pegs can light up one by one. The mark itself never rotates.
const PEGS = [
	"M33.7 17 L35.3 6.5 A3.3 3.3 0 0 0 28.7 6.5 L30.3 17 Z",
	"M43.81 22.6 L52.36 16.3 A3.3 3.3 0 0 0 47.7 11.64 L41.4 20.19 Z",
	"M47 33.7 L57.5 35.3 A3.3 3.3 0 0 0 57.5 28.7 L47 30.3 Z",
	"M41.4 43.81 L47.7 52.36 A3.3 3.3 0 0 0 52.36 47.7 L43.81 41.4 Z",
	"M30.3 47 L28.7 57.5 A3.3 3.3 0 0 0 35.3 57.5 L33.7 47 Z",
	"M20.19 41.4 L11.64 47.7 A3.3 3.3 0 0 0 16.3 52.36 L22.6 43.81 Z",
	"M17 30.3 L6.5 28.7 A3.3 3.3 0 0 0 6.5 35.3 L17 33.7 Z",
	"M22.6 20.19 L16.3 11.64 A3.3 3.3 0 0 0 11.64 16.3 L20.19 22.6 Z",
];
const POINTER = "M0 0 L0 15 L4.2 11 L7.2 17.6 L10 16.3 L7.1 9.9 L12.6 9.9 Z";

/**
 * The bare brass helm. `pegs` (0-1 each) and `ring`, `pointer` (0-1) drive the build-up;
 * each part scales in from its own spot, so the wheel assembles without turning.
 */
export const Helm: React.FC<{
	size: number;
	pegs: number[];
	ring: number;
	pointer: number;
	color?: string;
	style?: React.CSSProperties;
}> = ({ size, pegs, ring, pointer, color = C.brass, style }) => (
	<svg width={size} height={size} viewBox="0 0 64 64" style={style} role="img" aria-label="Tabkyra helm">
		<circle
			cx="32"
			cy="32"
			r="15"
			fill="none"
			stroke={color}
			strokeWidth="5"
			strokeDasharray={`${94.25 * ring} 94.25`}
			transform="rotate(-90 32 32)"
		/>
		{PEGS.map((d, i) => {
			const t = pegs[i] ?? 0;
			const a = (i * Math.PI) / 4;
			// Each peg grows outward from the rim along its own spoke.
			const ox = 32 + Math.sin(a) * 15;
			const oy = 32 - Math.cos(a) * 15;
			return (
				<path
					key={d}
					d={d}
					fill={color}
					opacity={Math.min(1, t * 1.5)}
					transform={`translate(${ox} ${oy}) scale(${t}) translate(${-ox} ${-oy})`}
				/>
			);
		})}
		<path
			d={POINTER}
			fill={color}
			stroke={color}
			strokeWidth="1.4"
			strokeLinejoin="round"
			opacity={pointer}
			transform={`translate(28 23.4) translate(6 9) scale(${0.4 + 0.6 * pointer}) translate(-6 -9)`}
		/>
	</svg>
);
